"""Tool decorator and execution context for builder-defined LLM tools.

Flow builders define custom LLM-callable tools in a ``tools.py`` file placed
next to their ``flow.yml``.  Each tool is an ``async`` function decorated with
:func:`tool` and optionally accepts a :class:`ToolContext` parameter (named
``context``) that provides read/write access to conversation state.

Example::

    from rasa.mantle.tools.decorator import tool, ToolContext
    from rasa.mantle.tools.result import ToolResult

    @tool(description="Return the user's current account balance.")
    async def check_balance(account_id: str, context: ToolContext) -> ToolResult:
        balance = await fetch_balance(account_id)
        return ToolResult(llm_response={"balance": balance})

    @tool(description="Execute a money transfer between accounts.")
    async def process_transfer(
        amount: float,
        from_account: str,
        to_account: str,
        context: ToolContext,
    ) -> ToolResult:
        await context.send("Processing your transfer now, one moment…")
        context.memory.set("transfer_status", "completed")
        return ToolResult(llm_response={"ok": True, "amount": amount})

A tool returns a :class:`~rasa.mantle.tools.result.ToolResult`; structured data
for the LLM goes in ``llm_response``. Messages are sent with ``context.send`` and
state is written with ``context.memory.set`` — both are side effects, not result
fields. Every entry written via ``context.memory.set`` must be declared in the
skill's or the project's ``memory.yml``; an undeclared write is rejected. The
``context`` parameter is injected by the runtime and is **excluded** from the
OpenAI tool schema; every other annotated parameter becomes a schema property.

Interruptions
-------------

A tool runs under the turn's interrupt signal (voice barge-in, session timeout,
explicit cancel). When one arrives, :exc:`asyncio.CancelledError` is raised at
whatever ``await`` the tool is suspended on and propagates through its helpers —
nothing needs wiring up. A tool cancelled that way leaves **no record of the
call** and does **not** advance the step, so it can run again on the next turn,
while memory it already wrote is kept.

For anything irreversible, check :attr:`ToolContext.is_cancelled` before
starting and write an idempotency key to memory before the call so a re-run can
detect it::

    @tool(description="Execute a money transfer between accounts.")
    async def process_transfer(amount: float, context: ToolContext) -> ToolResult:
        if ref := context.memory.get("transfer_ref"):
            return ToolResult(llm_response={"ok": True, "reference": ref})
        if context.is_cancelled:
            return ToolResult(llm_response={"ok": False, "reason": "interrupted"})
        ref = new_transfer_reference()
        context.memory.set("transfer_ref", ref)
        await bank.transfer(amount, idempotency_key=ref)
        return ToolResult(llm_response={"ok": True, "reference": ref})

Cleanup in an ``except asyncio.CancelledError`` block must re-raise and finish
fast: the runtime waits only briefly for an interrupted tool to unwind before it
stops waiting, so slow async cleanup is cut off part-way.
"""

from __future__ import annotations

from contextlib import asynccontextmanager
from typing import (
    TYPE_CHECKING,
    Any,
    AsyncIterator,
    Awaitable,
    Callable,
    Mapping,
    Optional,
    Sequence,
)

from rasa.mantle.state.tracker_handle import TrackerHandle
from rasa.mantle.tools.buttons import Button
from rasa.mantle.tools.result import ToolResult
from rasa.mantle.tools.tool_model_context import ToolModelContext

if TYPE_CHECKING:
    from rasa.mantle.content.responses import ResponseButton
    from rasa.mantle.memory.manager import MemoryManager
    from rasa.mantle.orchestration.turn_context import MessageTurnContext
    from rasa.shared.core.events import Event

ToolFunction = Callable[..., Awaitable[ToolResult]]


class MemorySlice:
    """A scoped, write-through slice of conversation memory for one tool call.

    Bound to one skill/flow pair, this is the tool-facing slice of memory for
    reading and writing conversation state. The pair is the active stack
    frame's skill/flow unless the engine passed an explicit invocation scope
    (memory validation tools during correction of a skill-scoped field).

    ``get`` accepts **bare** entry names (bound skill, then project) or
    **fully-qualified** slot names (``{skill_id}.{entry}``, ``project.{entry}``)
    with the same visibility as conditions / ``read_all``. ``set`` accepts
    bare names for the bound skill or project, plus ``project.{entry}``
    (project only) and ``{bound_skill_id}.{entry}`` (that skill only).
    Cross-skill writes are rejected.

    ``set`` writes through :class:`~rasa.mantle.memory.manager.MemoryManager`
    at call time — the value is validated against the skill's access contract
    and lands on the tracker immediately: ``None`` is a ``MemoryCleared``, and
    any other value (including ``False`` or ``0``) is a ``MemorySet``. ``get``
    returns the
    current value, unwrapped from its
    :class:`~rasa.mantle.memory.field.MemoryEntry`, or an optional caller
    default when the entry is denied, missing, or has no value.

    Tool functions should not construct this class directly; the runtime injects
    it via :attr:`ToolContext.memory`.
    """

    def __init__(self, memory: "MemoryManager", skill_id: str, flow_id: str) -> None:
        self._memory = memory
        self._skill_id = skill_id
        self._flow_id = flow_id

    def get(self, entry: str, default: Any = None) -> Any:
        """Return the current value of *entry*, or *default* when unset or denied.

        *entry* may be a bare name or a fully-qualified slot name. A read denied
        by the skill's access contract (or outside the readable set) is treated
        as unset. A readable slot whose current value is ``None`` is also
        treated as unset — :meth:`MemoryManager.get` returns a
        :class:`~rasa.mantle.memory.field.MemoryEntry` with ``value=None`` in
        that case, not ``None`` itself. Omit *default* to receive ``None``.
        Stored ``None`` cannot be distinguished from never-written and
        therefore also yields *default*, unlike ``dict.get``.

        Args:
            entry: Bare or fully-qualified memory name.
            default: Value returned when the entry is unset, ``None``, or
                unreadable.

        Returns:
            The stored value when it is not ``None``. Otherwise *default*
            (``None`` if the caller omitted it).
        """
        result = self._memory.get(self._skill_id, self._flow_id, entry)
        if result is None or result.value is None:
            return default
        return result.value

    def set(self, entry: str, value: Any) -> None:
        """Write *entry* → *value* through the memory system at call time.

        *entry* may be a bare name, ``project.{entry}`` (project only), or
        ``{bound skill id}.{entry}`` (that skill only). Cross-skill qualified
        names are rejected.

        Raises:
            rasa.mantle.memory.manager.MemoryWriteError: When *entry* is not
                declared in the skill's or the project's ``memory.yml``, the
                skill's access contract denies the write, the entry collides
                with the reserved ``system.*`` namespace, or a ``project.*``
                field is already set
                (:class:`~rasa.mantle.memory.manager.ProjectMemoryAlreadySetError`).
        """
        self._memory.set(self._skill_id, self._flow_id, entry, value)


def _builder_message_metadata(
    metadata: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Copy builder metadata with engine-owned keys removed.

    Filler flags, template names, response source, discarded markers, engine
    model timings, and tracker identity stay under the engine's control. Keys
    that name message fields are removed too, so they cannot replace the text
    or controls already set. The caller's mapping is not modified.
    """
    if not metadata:
        return None
    from rasa.core.constants import (
        BOT_UTTERANCE_AGENT_MESSAGE_TYPE_KEY,
        LLM_TIME_TO_FIRST_TOKEN_MS_KEY,
        LLM_TOTAL_TIME_MS_KEY,
    )
    from rasa.mantle.hooks.constants import DISCARDED_EVENT_METADATA_KEY
    from rasa.mantle.orchestration.turn_context import (
        RESPONSE_SOURCE_METADATA_KEY,
        UTTER_ACTION_METADATA_KEY,
    )
    from rasa.shared.constants import ASSISTANT_ID_KEY
    from rasa.shared.nlu.constants import (
        METADATA_DEFAULT_LANGUAGE,
        METADATA_MODEL_ID,
        METADATA_MODEL_NAME,
        METADATA_SESSION_ID,
    )

    blocked = {
        RESPONSE_SOURCE_METADATA_KEY,
        UTTER_ACTION_METADATA_KEY,
        BOT_UTTERANCE_AGENT_MESSAGE_TYPE_KEY,
        LLM_TIME_TO_FIRST_TOKEN_MS_KEY,
        LLM_TOTAL_TIME_MS_KEY,
        DISCARDED_EVENT_METADATA_KEY,
        METADATA_SESSION_ID,
        METADATA_MODEL_ID,
        METADATA_MODEL_NAME,
        METADATA_DEFAULT_LANGUAGE,
        ASSISTANT_ID_KEY,
        "text",
        "timestamp",
        "buttons",
        "quick_replies",
        "custom",
        "image",
        "attachment",
        "elements",
    }
    kept = {key: value for key, value in metadata.items() if key not in blocked}
    return kept or None


class ToolStream:
    """One open stream a tool writes while it is still running.

    The runtime yields this from :meth:`ToolContext.stream`. Builders do not
    construct it. Leaving the ``async with`` block records one agent message.
    """

    def __init__(
        self,
        turn: MessageTurnContext,
        buttons: Sequence[Button] | None = None,
        metadata: Mapping[str, Any] | None = None,
    ) -> None:
        self._turn = turn
        self._buttons = list(buttons or [])
        self._metadata = None if metadata is None else dict(metadata)

    async def write(self, text: str) -> None:
        """Push one text piece to the user when the channel streams.

        An empty string is ignored. On a channel that does not stream, the
        piece is held until the stream closes.

        Args:
            text: The next piece of the message.
        """
        await self._turn.write_tool_stream(text)

    def set_buttons(self, buttons: Sequence[Button]) -> None:
        """Replace the buttons attached when this stream finishes.

        This does not call :meth:`ToolContext.set_buttons`. An interrupted
        stream does not deliver these buttons.

        Args:
            buttons: Buttons for the finished stream. Replaces any previous set.
        """
        self._buttons = list(buttons)

    def set_metadata(self, metadata: Mapping[str, Any]) -> None:
        """Replace authoring metadata stored on the finished stream's message.

        Engine-owned keys (filler flags, template names, model timings) are
        removed when the stream closes. An interrupted stream stores none of
        this metadata.

        Args:
            metadata: Authoring fields. Replaces any previous set.
        """
        self._metadata = dict(metadata)


class ToolContext:
    """Read/write access to conversation state for in-process tool functions.

    The runtime creates one ``ToolContext`` per tool invocation and injects it
    as the ``context`` keyword argument.  Tool functions should not construct this
    class directly.
    """

    def __init__(
        self,
        tracker_handle: TrackerHandle,
        memory_scope: Optional[tuple[str, str]] = None,
    ) -> None:
        self._handle = tracker_handle
        self._memory_scope = memory_scope

    async def send(
        self,
        text: str,
        *,
        buttons: Sequence[Button] | None = None,
        metadata: Mapping[str, Any] | None = None,
    ) -> None:
        """Send a message to the user mid tool-call.

        Use this to acknowledge or update the user before the tool finishes
        (e.g. ``await context.send("Looking that up, one moment…")``).  The text is
        recorded on the tracker and streamed to the output channel immediately
        through the ambient turn context — no wiring is required from the tool.

        Optional buttons use the same :class:`Button` values as a named
        response. They are delivered with the text. Optional metadata is stored
        on the recorded message after engine-owned keys are removed.

        If the user has already interrupted the turn (voice barge-in) the
        message is dropped.

        Args:
            text: The message to send.
            buttons: Buttons to attach. ``None`` and an empty sequence attach
                none. This does not use :meth:`set_buttons`.
            metadata: Authoring fields stored on the message.

        Raises:
            LookupError: When called outside an established turn.
            RuntimeError: When a tool stream is still open.
        """
        from rasa.mantle.orchestration.turn_context import current_turn_context

        await current_turn_context().send(
            text,
            buttons=self._resolved_message_buttons(buttons),
            variant_metadata=_builder_message_metadata(metadata),
        )

    @asynccontextmanager
    async def stream(
        self,
        *,
        buttons: Sequence[Button] | None = None,
        metadata: Mapping[str, Any] | None = None,
    ) -> AsyncIterator[ToolStream]:
        """Stream a message to the user, then record it as one agent message.

        Write pieces with :meth:`ToolStream.write` inside the block. Channels
        that stream receive each piece as soon as they accept it, unless a
        ``modify_outgoing_text`` hook is registered. That hook holds every
        piece and sends the assembled text once, when the block ends, after
        the hook runs. Other channels receive the full text once, when the
        block ends. An empty stream records nothing.

        If the block raises, or the turn is already cancelled, playback closes
        as interrupted. Text already delivered is recorded. Text that never
        left a non-streaming channel is discarded.

        Buttons and metadata may be passed here or replaced on the stream
        before the block ends. They are delivered only when the stream
        finishes. :meth:`set_buttons` is a separate mechanism for named
        responses.

        Args:
            buttons: Buttons for the finished stream.
            metadata: Authoring fields stored on the finished message.

        Yields:
            The stream to write pieces into.

        Raises:
            LookupError: When called outside an established turn.
            RuntimeError: When another tool stream is already open.
        """
        from rasa.mantle.orchestration.turn_context import current_turn_context

        turn = current_turn_context()
        turn.begin_tool_stream()
        tool_stream: ToolStream | None = None
        completed = False
        try:
            tool_stream = ToolStream(turn, buttons, metadata)
            yield tool_stream
            completed = True
        finally:
            # Close even when constructing the stream or resolving its buttons
            # fails. Otherwise the turn keeps the stream open and later sends
            # fail.
            interrupted = not completed or turn.is_cancelled
            close_buttons: tuple[ResponseButton, ...] = ()
            close_metadata = None
            resolution_error: BaseException | None = None
            if tool_stream is not None and not interrupted:
                try:
                    close_buttons = self._resolved_message_buttons(tool_stream._buttons)
                    close_metadata = _builder_message_metadata(tool_stream._metadata)
                except BaseException as exc:
                    interrupted = True
                    close_buttons = ()
                    close_metadata = None
                    resolution_error = exc
            await turn.close_tool_stream(
                interrupted=interrupted,
                buttons=close_buttons,
                variant_metadata=close_metadata,
            )
            if resolution_error is not None:
                raise resolution_error

    def set_buttons(self, buttons: list[Button]) -> None:
        """Set the buttons for the response that invoked this source tool.

        Calling this method more than once replaces the previously supplied
        buttons. The values are attached to the named response after the tool
        finishes; messages emitted with :meth:`send` remain separate.

        Args:
            buttons: Buttons to attach to the response.

        Raises:
            RuntimeError: When this tool was not invoked as a response button
                source.
        """
        from rasa.mantle.orchestration.dynamic_buttons import set_source_buttons

        set_source_buttons(buttons)

    @property
    def is_cancelled(self) -> bool:
        """Whether the user has interrupted this turn (e.g. a voice barge-in).

        Check this immediately *before* starting something irreversible, and
        between consecutive side effects::

            if context.is_cancelled:
                return ToolResult(llm_response={"ok": False, "reason": "interrupted"})
            await bank.transfer(amount)

        Returning early is clean: the runtime records the call and advances the
        step with no further ``await``, so the interrupt cannot land in between.
        A tool cancelled mid-``await`` gets neither, and may run again on the
        next turn — guard irreversible work with an idempotency key.

        Place the check by what comes *next*, not by what came before: it
        guards the operation that follows it. Checking merely to find out
        whether the previous ``await`` was interrupted is redundant — that
        arrives as :exc:`asyncio.CancelledError`.

        Reads ambient turn state, so it reports ``False`` outside a turn and
        inside threads started by ``run_in_executor``.
        """
        from rasa.mantle.orchestration.turn_context import current_turn_context

        try:
            return current_turn_context().is_cancelled
        except LookupError:
            return False

    @property
    def memory(self) -> MemorySlice:
        """Scoped, write-through memory view for this invocation.

        Uses *memory_scope* when the engine supplied one (owning skill/flow of
        a correction write); otherwise resolves the active skill/flow from the
        current stack frame on **each** access so regular tools always reflect
        the current scope. :attr:`events` exposes the conversation history
        (read-only).
        """
        skill_id, flow_id = self._memory_scope or self._handle.memory_scope()
        return MemorySlice(self._handle.memory, skill_id, flow_id)

    @property
    def events(self) -> list[Event]:
        """Full conversation event history as a read-only copy.

        Returns a fresh list of the tracker's typed :class:`Event` objects (past
        user/bot messages, memory writes, …). It is a **copy** — appending to or
        removing from it does not touch the live tracker — so a tool can read
        history without any chance of mutating conversation state. Reads and
        writes of memory entries still go through :attr:`memory`.
        """
        return list(self._handle.tracker.events)

    @property
    def model(self) -> ToolModelContext:
        """Read-only model-static data (scope summary, LLM config, …)."""
        return self._handle.model_context

    def _resolved_message_buttons(
        self,
        buttons: Sequence[Button] | None,
    ) -> tuple[ResponseButton, ...]:
        """Resolve buttons for a message this tool sends, or return none.

        An empty sequence does not touch memory. Resolution uses the same
        rules as buttons on a named response, including which memory refs
        this skill may write.
        """
        if not buttons:
            return ()
        from rasa.mantle.orchestration.dynamic_buttons import resolve_buttons

        skill_id, _ = self._memory_scope or self._handle.memory_scope()
        keys = self._handle.memory.button_writable_memory_keys(skill_id or None)
        return resolve_buttons(buttons, writable_memory_keys=keys)


def tool(*, description: str) -> Callable[[ToolFunction], ToolFunction]:
    """Mark an async function as an LLM-callable tool.

    Sets ``_tool_description`` and ``_tool_name`` attributes on the decorated
    function.  The runtime uses these attributes to:

    * Detect which functions in a ``tools.py`` module are tools (via
      ``hasattr(obj, "_tool_description")``).
    * Generate the ``description`` field in the OpenAI tool schema.
    * Identify the tool by name in ``dispatch_tool_call``.

    Args:
        description: Human-readable summary the LLM sees in the tool schema.
            Write it from the LLM's perspective — describe *when* and *why*
            to call this tool.

    Returns:
        A decorator that attaches metadata attributes to the wrapped function
        without altering its call signature or behaviour.
    """

    def decorator(func: ToolFunction) -> ToolFunction:
        setattr(func, "_tool_description", description)
        setattr(func, "_tool_name", func.__name__)
        return func

    return decorator
